import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';
import { createCreditNote } from '../src/credits.js';

test('createCreditNote: happy path', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2024-0001');
  assert.equal(result.value.invoiceNumber, 'INV-2024-0001');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.amount, 5000);
  assert.equal(result.value.reason, 'Discount');
  assert.equal(result.value.date, '2024-10-20');
});

test('createCreditNote: on issued invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 10000, reason: 'Refund', date: '2024-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: on partially paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 50000, date: '2024-10-20' });
  const result = createCreditNote(paidResult.value, { amount: 10000, reason: 'Partial refund', date: '2024-10-25' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: on paid invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const paidResult = recordPayment(issuedResult.value, { amount: 109202, date: '2024-10-20' });
  const result = createCreditNote(paidResult.value, { amount: 20000, reason: 'Overpayment refund', date: '2024-10-25' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: draft invoice error', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result = createCreditNote(invoiceResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('createCreditNote: invalid amount - zero', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 0, reason: 'Discount', date: '2024-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote: invalid amount - negative', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: -5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote: invalid amount - float', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000.5, reason: 'Discount', date: '2024-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('createCreditNote: credit too high', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Invoice total is 109202, try to create credit for more
  const result = createCreditNote(issuedResult.value, { amount: 150000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.deepEqual(result, { ok: false, error: 'CREDIT_TOO_HIGH' });
});

test('createCreditNote: credit equal to invoice total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Invoice total is 109202
  const result = createCreditNote(issuedResult.value, { amount: 109202, reason: 'Full refund', date: '2024-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 109202);
});

test('createCreditNote: invalid date format', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-13-01' }, []);

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createCreditNote: numbering starts at 0001', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: increments counter', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, ['CN-2024-0001']);

  assert.equal(result.value.number, 'CN-2024-0002');
});

test('createCreditNote: separate counter from invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Even with many invoice numbers, credit notes start their own counter
  const result = createCreditNote(
    issuedResult.value,
    { amount: 5000, reason: 'Discount', date: '2024-10-20' },
    ['INV-2024-0001', 'INV-2024-0002', 'INV-2024-0003', 'INV-2024-0004', 'INV-2024-0005']
  );

  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: per-year counter', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // 2023 credit notes shouldn't affect 2024 counter
  const result = createCreditNote(
    issuedResult.value,
    { amount: 5000, reason: 'Discount', date: '2024-10-20' },
    ['CN-2023-0001', 'CN-2023-0002', 'CN-2023-0003']
  );

  assert.equal(result.value.number, 'CN-2024-0001');
});

test('createCreditNote: handles mixed invoice and credit numbers', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(
    issuedResult.value,
    { amount: 5000, reason: 'Discount', date: '2024-10-20' },
    ['INV-2024-0001', 'CN-2024-0001', 'INV-2024-0002', 'CN-2024-0002', 'INV-2024-0003']
  );

  assert.equal(result.value.number, 'CN-2024-0003');
});

test('createCreditNote: year boundary', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-12-31',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Creating a credit note in 2025 for a 2024 invoice
  const result = createCreditNote(
    issuedResult.value,
    { amount: 5000, reason: 'Discount', date: '2025-01-15' },
    ['CN-2024-0001', 'CN-2025-0001']
  );

  // Should get the next 2025 number
  assert.equal(result.value.number, 'CN-2025-0002');
});

test('createCreditNote: large amount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 1000000, reason: 'Large refund', date: '2024-10-20' }, []);

  // Invoice total is ~1092020, so 1000000 should be valid
  assert.equal(result.ok, true);
  assert.equal(result.value.amount, 1000000);
});

test('createCreditNote: reason can be empty string', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: '', date: '2024-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.reason, '');
});

test('createCreditNote: reason can be long', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const longReason = 'A'.repeat(1000);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: longReason, date: '2024-10-20' }, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.reason, longReason);
});

test('createCreditNote: multiple credit notes for same invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const cn1 = createCreditNote(issuedResult.value, { amount: 30000, reason: 'Partial 1', date: '2024-10-20' }, []);
  const cn2 = createCreditNote(issuedResult.value, { amount: 30000, reason: 'Partial 2', date: '2024-10-21' }, ['CN-2024-0001']);
  const cn3 = createCreditNote(issuedResult.value, { amount: 30000, reason: 'Partial 3', date: '2024-10-22' }, ['CN-2024-0001', 'CN-2024-0002']);

  assert.equal(cn1.value.number, 'CN-2024-0001');
  assert.equal(cn2.value.number, 'CN-2024-0002');
  assert.equal(cn3.value.number, 'CN-2024-0003');
});

test('createCreditNote: invoice number is preserved', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.equal(result.value.invoiceNumber, issuedResult.value.number);
});

test('createCreditNote: customer ID is preserved', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = createCreditNote(issuedResult.value, { amount: 5000, reason: 'Discount', date: '2024-10-20' }, []);

  assert.equal(result.value.customerId, 'C-002');
});

